export const LISTENING_RESPONSE_MASTER: ListeningQuestion[] = CHOOSE_RESPONSE_ROWS.map(
  ([
    idNum,
    difficulty,
    cefr,
    topic,
    speaker,
    voiceRole,
    utterance,
    options,
    correctAnswerIndex,
    explanation,
  ]) => {
    const shift = (idNum * 3 + 1) % 4;
    const rotatedOptions = [
      options[(0 + shift) % 4],
      options[(1 + shift) % 4],
      options[(2 + shift) % 4],
      options[(3 + shift) % 4],
    ];
    const rotatedCorrect = (correctAnswerIndex - shift + 4) % 4;
    return {
      id: `ls-m-cr-${String(idNum).padStart(3, '0')}`,
      section: 'listening',
      taskType: 'listen-choose-response',
      difficulty,
      topic,
      learningObjective:
        'Identify the pragmatically, contextually, and logically appropriate spoken response to an authentic campus or academic utterance.',
      skillFocus: 'Pragmatic Comprehension & Situational Response',
      estimatedTimeSec: 30,
      keywords: [topic.toLowerCase(), 'choose response', 'pragmatics'],
      cefr,
      sourceType: 'curated',
      reviewStatus: 'verified',
      scoreWeight: 1,
      audioId: `aud-m-cr-${String(idNum).padStart(3, '0')}`,
      title: `${topic} — Quick Exchange ${idNum}`,
      contextLabel: `${topic} · Spoken Response`,
      script: [{ speaker, voiceRole, text: utterance }],
      question: 'Choose the most natural and appropriate response to the speaker.',
      options: rotatedOptions,
      correctAnswerIndex: rotatedCorrect,
      explanation,
      hint: 'Listen for the speaker’s exact communicative intent (question, warning, request, or critique) rather than keyword traps.',
      packId: PACK_ID,
    };
  }
);
